<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Core\TenantFeatures;
use EventMenu\Services\TicketService;

$pdo=Database::connection();$slug=trim((string)($_GET['evento']??''));$error=null;
$s=$pdo->prepare('SELECT e.*,t.name tenant_name FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$slug]);$event=$s->fetch();if(!$event||!TenantFeatures::events((int)($event['tenant_id']??0))){http_response_code(404);exit('Evento não encontrado.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';else{try{$reservation=(new TicketService())->reservePublic((int)$event['id'],(int)($_POST['batch_id']??0),(int)($_POST['quantity']??1),['name'=>(string)($_POST['name']??''),'email'=>(string)($_POST['email']??''),'phone'=>(string)($_POST['phone']??'')],trim((string)($_POST['coupon']??''))?:null,trim((string)($_POST['promoter']??''))?:null);header('Location: '.app_url('pedido.php?t='.rawurlencode($reservation['public_token'])),true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}
}
$b=$pdo->prepare('SELECT b.*,tt.name ticket_type_name,tt.description ticket_type_description,tt.access_area,tt.capacity_total ticket_type_capacity,tt.active ticket_type_active FROM ticket_batches b LEFT JOIN ticket_types tt ON tt.id=b.ticket_type_id WHERE b.event_id=? AND b.active=1 ORDER BY COALESCE(tt.sort_order,9999),tt.name,b.id');$b->execute([$event['id']]);$batches=$b->fetchAll();
$count=$pdo->prepare('SELECT COUNT(*) FROM tickets WHERE tenant_id=? AND event_id=? AND status IN ("reserved","paid","checked_in")');$count->execute([$event['tenant_id'],$event['id']]);$usedCapacity=(int)$count->fetchColumn();$eventCapacity=$event['capacity_total']!==null?(int)$event['capacity_total']:null;$eventRemaining=$eventCapacity!==null?max(0,$eventCapacity-$usedCapacity):null;
$typeUsage=[];$tu=$pdo->prepare('SELECT b.ticket_type_id,COUNT(*) used FROM tickets t JOIN ticket_batches b ON b.id=t.batch_id WHERE t.tenant_id=? AND t.event_id=? AND b.ticket_type_id IS NOT NULL AND t.status IN ("reserved","paid","checked_in") GROUP BY b.ticket_type_id');$tu->execute([$event['tenant_id'],$event['id']]);foreach($tu->fetchAll() as$r)$typeUsage[(int)$r['ticket_type_id']]=(int)$r['used'];
function ev_money(int $c):string{return 'R$ '.number_format($c/100,2,',','.');}
function ev_color(mixed $value,string $fallback):string{$v=strtolower(trim((string)$value));return preg_match('/^#[0-9a-f]{6}$/',$v)?$v:$fallback;}
$primary=ev_color($event['primary_color']??'','#f4b942');$secondary=ev_color($event['secondary_color']??'','#121925');$text=ev_color($event['text_color']??'','#f5f7fb');$subtitle=trim((string)($event['public_subtitle']??''));$salesEnabled=(int)($event['sales_enabled']??1)===1;$mapUrl=trim((string)($event['map_url']??''));$lat=$event['latitude']!==null?(float)$event['latitude']:null;$lng=$event['longitude']!==null?(float)$event['longitude']:null;$canonical=app_url('evento.php?evento='.rawurlencode($slug));
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($secondary) ?>"><title><?= Security::e($event['name']) ?> — EventMenu</title><meta name="description" content="<?= Security::e($subtitle!==''?$subtitle:mb_substr(strip_tags((string)$event['description']),0,180)) ?>"><link rel="canonical" href="<?= Security::e($canonical) ?>"><style>
:root{--bg:#090d14;--surface:<?= Security::e($secondary) ?>;--primary:<?= Security::e($primary) ?>;--text:<?= Security::e($text) ?>;--muted:color-mix(in srgb,var(--text) 62%,transparent);--line:color-mix(in srgb,var(--text) 14%,transparent)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 0,color-mix(in srgb,var(--primary) 18%,transparent),transparent 33%),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button,input,select{font:inherit}.shell{width:min(1120px,100%);margin:auto;padding:18px 18px 70px}.top{display:flex;justify-content:space-between;align-items:center;padding:8px 0 18px}.brand{font-size:18px;font-weight:900}.brand span{color:var(--primary)}.hero{position:relative;overflow:hidden;border-radius:30px;border:1px solid var(--line);background:linear-gradient(135deg,color-mix(in srgb,var(--primary) 18%,var(--surface)),var(--surface));min-height:430px;display:flex;align-items:end}.hero.with-banner{background-size:cover;background-position:center}.hero::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 5%,rgba(6,9,14,.18) 38%,rgba(6,9,14,.93) 100%)}.hero-body{position:relative;z-index:1;padding:clamp(25px,6vw,56px);max-width:820px}.eyebrow{font-size:11px;font-weight:900;letter-spacing:.16em;color:var(--primary)}h1{font-size:clamp(42px,8vw,82px);line-height:.92;letter-spacing:-2px;margin:10px 0 14px}.subtitle{font-size:clamp(17px,2vw,23px);line-height:1.35;margin:0 0 16px}.description{line-height:1.65;color:var(--muted);max-width:720px}.meta{display:flex;gap:9px;flex-wrap:wrap;margin-top:20px}.pill{padding:9px 12px;border:1px solid var(--line);border-radius:999px;background:rgba(12,16,23,.7);font-size:13px;font-weight:750}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,.7fr);gap:20px;margin-top:22px}.section,.side-card{border:1px solid var(--line);border-radius:25px;background:color-mix(in srgb,var(--surface) 92%,#000 8%);padding:22px}.section-head{display:flex;justify-content:space-between;gap:15px;align-items:end;margin-bottom:17px}.section-head h2,.side-card h2{margin:0;font-size:25px}.muted{color:var(--muted)}.ticket-grid{display:grid;gap:13px}.ticket{border:1px solid var(--line);border-radius:20px;padding:18px;background:rgba(0,0,0,.12)}.ticket-top{display:flex;justify-content:space-between;gap:12px}.ticket h3{margin:5px 0;font-size:22px}.price{font-size:22px;font-weight:950;color:var(--primary)}.availability{font-size:12px;color:var(--muted)}.buy{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:15px}.buy label{display:grid;gap:5px;font-size:11px;font-weight:800;color:var(--muted)}.buy input,.buy select{width:100%;border:1px solid var(--line);background:#090d14;color:var(--text);border-radius:12px;padding:11px}.buy button{grid-column:1/-1;border:0;background:var(--primary);color:#171208;border-radius:13px;padding:13px;font-weight:950;cursor:pointer}.alert{padding:13px 15px;border-radius:15px;background:#421d25;color:#ffd8de;border:1px solid #65303b;margin-top:18px}.closed{padding:13px;border:1px solid var(--line);border-radius:14px;color:var(--muted);margin-top:12px}.map-box{border:1px solid var(--line);border-radius:18px;overflow:hidden;margin-top:12px;background:#0c1017}.map-box iframe{border:0;width:100%;height:240px;display:block}.map-link{display:block;padding:12px 14px;font-weight:800;color:var(--primary)}.capacity{font-size:34px;font-weight:950;display:block;margin:5px 0}.powered{text-align:center;color:var(--muted);font-size:12px;padding-top:34px}@media(max-width:850px){.shell{padding:10px 10px 60px}.hero{min-height:390px;border-radius:23px}.grid{grid-template-columns:1fr}.buy{grid-template-columns:1fr}.buy button{grid-column:auto}h1{letter-spacing:-1px}.section,.side-card{padding:17px;border-radius:20px}}
</style></head><body><main class="shell"><header class="top"><div class="brand">EventMenu <span>Premium</span></div><span class="muted"><?= Security::e($event['tenant_name']) ?></span></header>
<section class="hero<?= $event['banner_url']?' with-banner':'' ?>"<?php if($event['banner_url']):?> style="background-image:linear-gradient(180deg,rgba(5,8,12,.16),rgba(5,8,12,.74)),url('<?= Security::e($event['banner_url']) ?>')"<?php endif;?>><div class="hero-body"><span class="eyebrow"><?= Security::e(mb_strtoupper((string)($event['event_type']??'EVENTO'))) ?></span><h1><?= Security::e($event['name']) ?></h1><?php if($subtitle!==''):?><p class="subtitle"><?= Security::e($subtitle) ?></p><?php endif;?><div class="description"><?= nl2br(Security::e($event['description']??'')) ?></div><div class="meta"><span class="pill">📅 <?= Security::e(date('d/m/Y',strtotime($event['starts_at']))) ?></span><span class="pill">🕒 <?= Security::e(date('H:i',strtotime($event['starts_at']))) ?></span><?php if($event['venue']):?><span class="pill">📍 <?= Security::e($event['venue']) ?></span><?php endif;?><?php if($eventCapacity!==null):?><span class="pill">🎟 Capacidade <?= $eventCapacity ?></span><?php endif;?></div></div></section>
<?php if($error):?><div class="alert"><?= Security::e($error) ?></div><?php endif;?>
<div class="grid"><section class="section"><div class="section-head"><div><span class="eyebrow">INGRESSOS</span><h2>Escolha seu ingresso</h2></div><span class="muted">QR individual após confirmação</span></div><?php if(!$salesEnabled):?><div class="closed"><strong>Venda online temporariamente indisponível.</strong><br>A organização desativou novas compras para este evento.</div><?php elseif(!$batches):?><div class="closed">Nenhum lote disponível no momento.</div><?php else:?><div class="ticket-grid"><?php foreach($batches as$batch):$available=max(0,(int)$batch['quantity_total']-(int)$batch['quantity_sold']-(int)$batch['quantity_reserved']);if($eventRemaining!==null)$available=min($available,$eventRemaining);if(!empty($batch['ticket_type_id'])&&!empty($batch['ticket_type_capacity'])){$typeRemaining=max(0,(int)$batch['ticket_type_capacity']-($typeUsage[(int)$batch['ticket_type_id']]??0));$available=min($available,$typeRemaining);} $now=time();$open=(!$batch['sales_start']||strtotime($batch['sales_start'])<=$now)&&(!$batch['sales_end']||strtotime($batch['sales_end'])>=$now);$free=(int)$batch['price_cents']===0;?><article class="ticket"><div class="ticket-top"><div><span class="eyebrow"><?= Security::e($batch['ticket_type_name']?:'INGRESSO') ?></span><h3><?= Security::e($batch['name']) ?></h3><?php if($batch['access_area']):?><div class="availability">Acesso: <?= Security::e($batch['access_area']) ?></div><?php endif;?></div><div class="price"><?= $free?'Grátis':ev_money((int)$batch['price_cents']) ?></div></div><?php if($batch['ticket_type_description']):?><p class="muted"><?= Security::e($batch['ticket_type_description']) ?></p><?php endif;?><div class="availability"><?= $available ?> disponível(is) neste momento</div><?php if($available>0&&$open&&empty($batch['ticket_type_id'])||($available>0&&$open&&(int)$batch['ticket_type_active']===1)):?><form method="post" class="buy"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><label>Quantidade<select name="quantity"><?php for($i=1;$i<=min(10,$available);$i++):?><option value="<?= $i ?>"><?= $i ?></option><?php endfor;?></select></label><label>Nome<input name="name" required autocomplete="name"></label><label>E-mail<input type="email" name="email" autocomplete="email"></label><label>Telefone<input name="phone" autocomplete="tel"></label><label>Cupom <span class="muted">opcional</span><input name="coupon" autocomplete="off"></label><label>Promotor / afiliado <span class="muted">opcional</span><input name="promoter" autocomplete="off"></label><button><?= $free?'Emitir ingresso':'Reservar e pagar' ?></button></form><?php elseif(!$open):?><div class="closed">Fora do período de venda.</div><?php elseif($available<=0):?><div class="closed">Esgotado / capacidade atingida.</div><?php else:?><div class="closed">Tipo de ingresso indisponível.</div><?php endif;?></article><?php endforeach;?></div><?php endif;?></section>
<aside><section class="side-card"><span class="eyebrow">LOCAL</span><h2><?= Security::e($event['venue']?:'Local do evento') ?></h2><?php if($event['address']):?><p class="muted"><?= Security::e($event['address']) ?></p><?php endif;?><?php if($lat!==null&&$lng!==null):$bbox=($lng-0.008).','.($lat-0.006).','.($lng+0.008).','.($lat+0.006);$osm='https://www.openstreetmap.org/export/embed.html?bbox='.rawurlencode($bbox).'&layer=mapnik&marker='.rawurlencode($lat.','.$lng);?><div class="map-box"><iframe title="Mapa do evento" loading="lazy" referrerpolicy="no-referrer" src="<?= Security::e($osm) ?>"></iframe><?php if($mapUrl!==''):?><a class="map-link" href="<?= Security::e($mapUrl) ?>" target="_blank" rel="noopener noreferrer">Abrir rota / mapa ↗</a><?php endif;?></div><?php elseif($mapUrl!==''):?><a class="map-link" href="<?= Security::e($mapUrl) ?>" target="_blank" rel="noopener noreferrer">Abrir localização no mapa ↗</a><?php endif;?></section><?php if($eventCapacity!==null):?><section class="side-card" style="margin-top:16px"><span class="eyebrow">CAPACIDADE</span><strong class="capacity"><?= $eventRemaining ?></strong><span class="muted">vaga(s) ainda disponíveis considerando reservas e ingressos emitidos</span></section><?php endif;?><section class="side-card" style="margin-top:16px"><span class="eyebrow">ACESSO</span><h2>Entrada por QR</h2><p class="muted">Cada ingresso possui QR Code individual. O código é validado no check-in e não pode ser utilizado duas vezes.</p></section></aside></div><footer class="powered">Powered by <strong>EventMenu</strong></footer></main></body></html>
